class Retailer:
    def __init__(self, stock_level: int, restock_rate: int, price_per_mask: float, supply_reliability: float):
        self.stock_level = int(stock_level)
        self.restock_rate = int(restock_rate)
        self.price_per_mask = float(price_per_mask)
        self.supply_reliability = float(supply_reliability)

    def sell_masks(self, qty: int) -> bool:
        if self.stock_level >= qty:
            self.stock_level -= qty
            return True
        return False

    def restock(self, rng: np.random.Generator):
        if rng.random() < self.supply_reliability:
            self.stock_level += self.restock_rate

    def update_price(self, demand_factor: float = 1.0):
        self.price_per_mask = max(0.1, self.price_per_mask * demand_factor)

def compute_neighbor_shares(persons: Dict[int, Person], prev_state: Dict[int, bool]) -> Dict[int, Dict[str, float]]:
    shares = {}
    for pid, p in persons.items():
        res = {}
        for L, neighs in p.neighbors_by_layer.items():
            if not neighs:
                res[L] = 0.0
                continue
            vals = [1.0 if prev_state.get(j, False) else 0.0 for j in neighs]
            res[L] = float(np.mean(vals)) if vals else 0.0
        shares[pid] = res
    return shares
